"""Regenerate the source mapping and role reference from the packaged catalogue."""

import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def main():
    catalogue = json.loads((ROOT / "src/energy_agents/data/career_roles/catalogue.json").read_text())
    lines = [
        ".. Generated by scripts/render_career_role_docs.py; edit the catalogue first.", "",
        "Neutral source index", "~~~~~~~~~~~~~~~~~~~~", "",
        "These internal labels preserve coverage without identifying employers or linking",
        "to their postings. They are not publicly verifiable source citations.", "",
        ".. list-table:: All reviewed role descriptions, including equivalent variants",
        "   :header-rows: 1", "   :widths: 25 75", "",
        "   * - Neutral source label", "     - Generic agent", "",
    ]
    roles = {r["id"]: r for r in catalogue["roles"]}
    for listing in catalogue["listings"]:
        role = roles[listing["agent_id"]]
        lines.extend([
            f"   * - ``{listing['id']}``",
            f"     - :ref:`{role['title']} <{role['id']}>`",
        ])
    lines.extend(["", "Role contracts", "~~~~~~~~~~~~~~", ""])
    for family in sorted({r["family"] for r in roles.values()}):
        lines.extend([family, "^" * len(family), ""])
        for role in (r for r in roles.values() if r["family"] == family):
            lines.extend([
                f".. _{role['id']}:", "", f"**{role['title']}**", "",
                f"``{role['id']}`` — {role['mandate']}", "",
                "Responsibilities:", "",
                *[f"* {item}." for item in role["responsibilities"]], "",
                "Required inputs: " + ", ".join(f"``{v}``" for v in role["required_inputs"]) + ".",
                "", "Deliverables: " + ", ".join(f"``{v}``" for v in role["deliverables"]) + ".",
                "", "Review checks:", "",
                *[f"* {item}." for item in role["review_checks"]], "",
                "Suggested KPIs: " + ", ".join(f"``{v}``" for v in role["kpis"]) + ".", "",
                "Handoffs: " + ", ".join(f":ref:`{roles[v]['title']} <{v}>`"
                                          for v in role["handoffs"]) + ".", "",
            ])
    (ROOT / "docs/sphinx/source/career_role_mapping.inc").write_text(
        "\n".join(lines), encoding="utf-8")


if __name__ == "__main__":
    main()
